import{_ as e,o as n,c as s,ag as t}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"科学日报 · 2026-10-29（神经科学 / 皮层发育 · 围产期清除基因组异常神经元）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/neuroscience/science-daily-2026-10-29-neuro.md","filePath":"topics/neuroscience/science-daily-2026-10-29-neuro.md"}'),i={name:"topics/neuroscience/science-daily-2026-10-29-neuro.md"};function c(r,o,d,l,a,g){return n(),s("div",null,[...o[0]||(o[0]=[t('<h1 id="科学日报-·-2026-10-29-神经科学-皮层发育-·-围产期清除基因组异常神经元" tabindex="-1">科学日报 · 2026-10-29（神经科学 / 皮层发育 · 围产期清除基因组异常神经元） <a class="header-anchor" href="#科学日报-·-2026-10-29-神经科学-皮层发育-·-围产期清除基因组异常神经元" aria-label="Permalink to &quot;科学日报 · 2026-10-29（神经科学 / 皮层发育 · 围产期清除基因组异常神经元）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-29.md</code> — 第48期 ｜ 科学板块（1 篇） 落盘说明：文件名带 <code>-neuro</code> 后缀，避免与其它主题同日同名文件互引产生伪边（见 <code>topics/ai-brain/auto-link-quality-fixes.md</code>）。</p></blockquote><hr><h2 id="科学日报-2026-10-29-出生前后大脑「清算」数十亿基因组异常的神经元" tabindex="-1">科学日报 2026-10-29：出生前后大脑「清算」数十亿基因组异常的神经元 <a class="header-anchor" href="#科学日报-2026-10-29-出生前后大脑「清算」数十亿基因组异常的神经元" aria-label="Permalink to &quot;科学日报 2026-10-29：出生前后大脑「清算」数十亿基因组异常的神经元&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-29.md</code> ｜ DOI: 10.1038/s41586-026-11190-3 ｜ Nature (2026)</p></blockquote><ul><li>问题：人神经元<strong>终末分化、长寿命、剂量敏感</strong>（CNV 与杂合点突变关联多种神经发育与精神疾病）。那么<strong>成年大脑里的神经元，基因组质量到底有多「干净」？是怎么变干净的？</strong></li><li>方法：对<strong>胎儿到出生后的人脑做 2,357 个单神经元全基因组测序</strong>（两种 scWGS），并用 <strong>44,861 个核的 snATAC/snRNA</strong> 做转录/染色质层面的关联。</li><li>结果（实测）： <ul><li><strong>产前皮层神经元平均 25.9%（区间 12.7%–46%）携带高度异常的基因组</strong>——即涉及多条染色体的<strong>广泛 CNV</strong>；</li><li><strong>出生后这一比例下降约 4.5 倍</strong>（Fisher 合并 P = 3.5×10⁻⁶）；广泛 CNV 者主要在<strong>围产期被淘汰</strong>，时间大致<strong>与程序性细胞死亡期平行</strong>；<strong>CNV 负荷较小的神经元随产后年龄缓慢减少</strong>；</li><li>存活神经元的 CNV <strong>显著缺失剂量敏感基因与神经发育障碍相关基因</strong>（超几何检验 P&lt;0.05）→ <strong>存在选择性淘汰</strong>；</li><li><strong>高 CNV 负荷的神经元突触基因表达异常</strong> → 异常的突触基因调控很可能是<strong>被清除的诱因</strong>。</li></ul></li><li>洞察（对本库 <code>neuroscience</code> × <code>biomedicine</code>）： <ol><li><strong>「发育不是加法，是加法 + 主动减法」</strong> —— 成熟大脑的基因组质量<strong>不是天生的</strong>，而是靠<strong>围产期的一场主动筛选</strong>换来的。判据：<strong>当一个成熟系统表现出「一致的优质属性」时，先问它是「天生如此」还是「经过了一轮淘汰」——后者往往预示存在可识别的筛选信号（这里是突触基因失调）。</strong> 这与 10-25「细胞类型被拆成可寻址亚型」、10-26「学习子系统 vs 操控子系统」同族：<strong>发育/演化的『质』常靠选择而非构造。</strong></li><li><strong>「突触基因失调 = 淘汰的读取信号」</strong> —— 被清除的神经元<strong>功能上先异常</strong>（突触基因表达乱），再被移走。可迁移判据：<strong>在发育/质量控制场景中，把「功能异常」当作剔除信号来读（而非只看结构破损），能更早识别该被移除的单元。</strong></li><li><strong>一句话定位</strong>：<strong>正常大脑的基因组多样性远高于预期，而稳态靠围产期主动清算维持</strong>——为「体细胞突变 × 神经发育障碍」提供了时间窗与机制线索。</li></ol></li></ul><hr><blockquote><p>📎 关联主题：<code>topics/neuroscience/index.md</code> ｜ <code>topics/biomedicine/index.md</code> ｜ 第48期 科学板块</p></blockquote><p>关键词：科学日报第48期、单神经元全基因组测序 scWGS、2357 神经元、皮层神经元、广泛 CNV、产前 25.9%、出生后降 4.5 倍、围产期清除、程序性细胞死亡、剂量敏感基因、神经发育障碍基因、超几何检验、选择性淘汰、snATAC snRNA、突触基因表达异常、基因组质量非天生、主动减法、体细胞突变、人脑体细胞镶嵌</p><p>关联：<code>topics/neuroscience/index.md</code>、<code>topics/neuroscience/science-daily-2026-10-26-neuro.md</code>（HD 环形吸引子/脑细胞缩放律）、<code>topics/neuroscience/science-daily-2026-10-25-neuro.md</code>（CD51 星形胶质细胞亚型）、<code>topics/biomedicine/science-daily-2026-10-12.md</code>（人类心脏发育单细胞图谱）、<code>topics/biomedicine/science-daily-2026-10-29-biomed.md</code></p>',10)])])}const m=e(i,[["render",c]]);export{p as __pageData,m as default};
